  assert.equal(abortCalls, 0);
  assert.equal(closeCalls, 1);
});

test('cancellation during a throwing sink takes priority over the sink error', async () => {
  const controller = new AbortController();
  const reason = { cause: 'sink-cancel-before-error-handling' };
  const error = new Error('sink error');

  let abortCalls = 0;
  let closeCalls = 0;

  const result = await consumeBatches({
    cursor: {
      take() {
        return Promise.resolve({
          rows: ['row'],
          end: true,
        });
